// Run against a fresh labeled control generated by scripts/telemetry_query_fixture.py.
const {chromium}=require(process.env.PLAYWRIGHT_MODULE||'playwright');
const assert=require('node:assert/strict');
const fs=require('node:fs');
const base=process.env.REVIEW_TEST_URL,output=process.env.REVIEW_OUTPUT_DIR;
(async()=>{
 const browser=await chromium.launch({headless:true,channel:'msedge'}),errors=[];
 try{
  const page=await browser.newPage({viewport:{width:1440,height:1100},acceptDownloads:true});
  page.on('pageerror',e=>errors.push(e.message));
  const requests=[];page.on('request',r=>{if(r.url().includes('/api/trainer-telemetry/'))requests.push(r.url());});
  await page.goto(base+'/?view=health&experiment=long-telemetry-control&signals_smooth=10');
  const board=page.locator('#trainer-telemetry');await board.getByRole('button',{name:'Browse metrics',exact:true}).waitFor();
  await page.waitForFunction(()=>!document.querySelector('#trainer-telemetry').hasAttribute('aria-busy'));
  assert.match(await board.innerText(),/50,001 logs/);
  assert.match(await board.innerText(),/64 of 106 metric series/);
  const kl=board.locator('[data-signal-group="kl"]');
  const outcome=board.locator('[data-signal-group="reward"]');
  assert.match(await outcome.innerText(),/Synthetic solve rate/);
  assert.ok(await outcome.locator('circle').count()>10);
  await kl.getByRole('button',{name:/learner_update 37:/}).waitFor();
  assert.match(await kl.innerText(),/50,000\/50,000 measured/);
  if(output)await board.screenshot({path:output+'/full-run-desktop.png'});
  await board.getByRole('button',{name:'Browse metrics',exact:true}).click();
  const catalog=page.getByRole('dialog',{name:'Metric catalog'});
  await catalog.getByRole('searchbox',{name:'Search metrics'}).fill('metric-099');
  await catalog.getByRole('button',{name:'Search',exact:true}).click();
  await catalog.getByText('1 matching series · learner_update',{exact:true}).waitFor();
  await catalog.getByRole('button',{name:'Add chart',exact:true}).click();
  await board.locator('[data-signal-group^="extra/"]').filter({hasText:'custom/metric-099'}).waitFor();
  await board.getByRole('spinbutton',{name:'From step'}).fill('0');
  await board.getByRole('spinbutton',{name:'To step'}).fill('150');
  await board.getByRole('button',{name:'Select interval',exact:true}).click();
  await board.getByText('151 / 50,001 logs in interval',{exact:true}).waitFor();
  assert.match(await kl.innerText(),/151\/151 measured/);
  const selected=requests.filter(x=>x.includes('/query?')).at(-1),cutoff=new URL(selected).searchParams.get('as_of');
  assert.equal(cutoff,'50001');
  // A late conflicting record must not alter the selected capture; Resume explicitly includes it.
  const native=await (await fetch(base+'/api/trainer-telemetry/export?experiment=long-telemetry-control&start=37&end=37')).text();
  const packet=JSON.parse(native.trim().split('\n')[0]);packet.records[0].id='late-ui-conflict';packet.records[0].metrics.kl.value=.003;
  const posted=await fetch(base+'/api/trainer-telemetry',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(packet)});assert.equal(posted.status,200);
  await board.getByRole('combobox',{name:'Trend',exact:true}).selectOption('50');
  await page.waitForFunction(()=>!document.querySelector('#trainer-telemetry').hasAttribute('aria-busy'));
  assert.match(await kl.innerText(),/151\/151 measured/);
  assert.equal(new URL(requests.filter(x=>x.includes('/query?')).at(-1)).searchParams.get('as_of'),cutoff);
  await page.reload();await board.getByRole('button',{name:'Resume updates',exact:true}).waitFor();
  assert.match(await kl.innerText(),/151\/151 measured/);
  assert.equal(new URL(requests.filter(x=>x.includes('/query?')).at(-1)).searchParams.get('as_of'),cutoff);
  await kl.getByRole('button',{name:'Inspect updates',exact:true}).click();
  const updates=page.getByRole('dialog',{name:'Recorded updates in interval'});
  await updates.getByRole('button',{name:'learner_update 37 · 1.8 nats',exact:true}).waitFor();
  assert.equal(await updates.locator('.telemetry-log-list button').count(),50);
  await updates.getByRole('button',{name:'Show more updates',exact:true}).click();
  await page.waitForFunction(()=>document.querySelectorAll('.telemetry-dialog .telemetry-log-list button').length===100);
  await updates.getByRole('button',{name:'Close',exact:true}).click();
  await board.locator('.telemetry-options > summary').click();
  await board.getByRole('button',{name:'Export comparison',exact:true}).click();
  const exports=page.getByRole('dialog',{name:'Export training signals'}),download=page.waitForEvent('download');
  await exports.getByRole('link',{name:'Download original JSONL · long-telemetry-control'}).click();
  const file=await download,records=fs.readFileSync(await file.path(),'utf8').trim().split('\n').map(JSON.parse);
  assert.equal(records.length,151);assert.equal(records.find(p=>p.records[0].step===37).records[0].metrics.kl.value,1.8);
  await exports.getByRole('button',{name:'Close',exact:true}).click();
  await board.getByRole('button',{name:'Resume updates',exact:true}).click();
  await board.getByText('152 / 50,002 logs in interval',{exact:true}).waitFor();
  assert.match(await kl.innerText(),/150\/151 measured/);
  await board.getByRole('spinbutton',{name:'From step'}).fill('60000');await board.getByRole('spinbutton',{name:'To step'}).fill('60010');
  await board.getByRole('button',{name:'Select interval',exact:true}).click();
  await board.getByText('0 / 50,002 logs in interval',{exact:true}).waitFor();
  await board.getByRole('button',{name:'Full range',exact:true}).click();
  await board.getByText('50,002 logs',{exact:true}).waitFor();
  assert.equal(await board.getByRole('spinbutton',{name:'To step'}).inputValue(),'49999');
  await page.setViewportSize({width:390,height:900});
  assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));
  await board.getByRole('button',{name:'Browse metrics',exact:true}).click();
  await catalog.getByText(/matching series/).waitFor();
  assert.ok(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+1));
  if(output)await page.screenshot({path:output+'/metric-catalog-mobile.png'});
  assert.deepEqual(errors,[]);
  console.log('Passed: full 50k run, early spike, complete counts, metric search, raw pagination, frozen late arrival, original export, explicit resume, empty interval and mobile layout.');
 }finally{await browser.close();}
})().catch(e=>{console.error(e);process.exit(1);});
